"""HTTP job retry scheduling; public function signature must remain stable."""
def retry_delays(attempts, base=0.25, cap=10.0):
    if attempts < 0 or base <= 0 or cap < base:
        raise ValueError("invalid retry bounds")
    return [min(cap, base * (2 ** index)) for index in range(attempts)]

f2.storage.py:
"""In-memory storage used by the namespace cache service."""
class Storage:
    def __init__(self):
        self.entries = {}

    def put(self, namespace, key, value, expires):
        self.entries[(namespace, key)] = (value, expires)

    def get(self, namespace, key, now, default=None):
        entry = self.entries.get((namespace, key))
        if entry is None or entry[1] <= now:
            return default
        return entry[0]

f2.service.py:
from storage import Storage

class Cache:
    def __init__(self, clock):
        self.clock = clock
        self.storage = Storage()

    def put(self, namespace, key, value, ttl):
        if ttl < 0:
            raise ValueError("negative TTL")
        self.storage.put(namespace, key, value, self.clock() + ttl)

    def get(self, namespace, key, default=None):
        return self.storage.get(namespace, key, self.clock(), default)
